import{_ as a,o as i,c as o,a3 as t}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"Full-Storage Overflow Compatible with 1.5 Automatic Gross Production","description":"","frontmatter":{"translationSource":{"title":"兼容1.5智能毛产的满仓溢流方案","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=nhFNnz7suUdKtA9LLLBMc0","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-overflow-compatible-with-1-5-automatic-gross-production"}]]},"headers":[],"relativePath":"full-storage-overflow-compatible-with-1-5-automatic-gross-production.md","filePath":"logistics/src/page-nhFNnz7suUdKtA9LLLBMc0.md"}'),r={name:"full-storage-overflow-compatible-with-1-5-automatic-gross-production.md"};function s(n,e,l,p,d,c){return i(),o("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><span class="logistics-source-anchor" id="兼容1-5智能毛产的满仓溢流方案" aria-hidden="true"></span><h1 id="full-storage-overflow-compatible-with-1-5-automatic-gross-production" tabindex="-1">Full-Storage Overflow Compatible with 1.5 Automatic Gross Production <a class="header-anchor" href="#full-storage-overflow-compatible-with-1-5-automatic-gross-production" aria-label="Permalink to &quot;Full-Storage Overflow Compatible with 1\\.5 Automatic Gross Production&quot;">​</a></h1><blockquote><p>Source page ID: <code>nhFNnz7suUdKtA9LLLBMc0</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=nhFNnz7suUdKtA9LLLBMc0" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red">Full-storage overflow has a small update for 1.6. Before updating, do not route Xiragen from the new map back here, or you risk running short of Separator Cores.</span></p><p><span id="source-block-VKXHUYaSRClJpyV7H8iLB8"></span></p><span class="logistics-source-anchor" id="前言" aria-hidden="true"></span><h3 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h3><p>Our 1.5 automatic gross-production setup used the brute-force technique of empty-storage balancing. As the number of samples grew rapidly, however, we found that unloaders providing oversupply could fail to unload for extended periods. This “loss of oversupply” blocks lines such as Xircon.</p><p>The Development Bureau therefore offers two approaches: full-storage oscillation and full-storage overflow.</p><p><span id="source-block-GixtqDUEdoS2IjSB4OGMny"></span></p><span class="logistics-source-anchor" id="接下来本文讲解满仓溢流的思路-并给出安装蓝图" aria-hidden="true"></span><h2 id="this-article-explains-full-storage-overflow-and-provides-installation-blueprints" tabindex="-1">This Article Explains Full-Storage Overflow and Provides Installation Blueprints <a class="header-anchor" href="#this-article-explains-full-storage-overflow-and-provides-installation-blueprints" aria-label="Permalink to &quot;This Article Explains Full-Storage Overflow and Provides Installation Blueprints&quot;">​</a></h2><p>Author: BEAR (credits at the end). This article primarily exchanges design ideas; blueprint codes and ease of copying still need optimization.</p><p><span id="source-block-FwzKgopE0eOZE7ZLYr0CuL"></span></p><span class="logistics-source-anchor" id="核心思路" aria-hidden="true"></span><h3 id="core-idea" tabindex="-1">Core Idea <a class="header-anchor" href="#core-idea" aria-label="Permalink to &quot;Core Idea&quot;">​</a></h3><p>First answer two questions: what is full-storage overflow? How does it guarantee ample Xircon/Separator Core inputs while avoiding the oversupply required by empty-storage balancing, and thus the possibility of losing that oversupply?</p><p>Full-storage overflow means applying overflow routing where solid Xiranite/Cuprium is originally produced. These two inputs for Xircon/Separator Core enter depot storage first; surplus Xiranite/Cuprium becomes Heavy Xiranite/Cuprium Powder locally.</p><p>Solid Xiranite/Cuprium has priority for storage, while Heavy Xiranite/Cuprium Powder inputs are not unloaded from storage. Xircon/Separator Core therefore receives ample inputs with priority.</p><p>That is: overflow provides supply priority; full storage ensures sufficient supply.</p><p>Empty-storage balancing, full-storage oscillation and full-storage overflow have no absolute ranking. Here are the latter&#39;s advantages and disadvantages, so you can choose for your needs:</p><p><span id="source-block-FW2RdpA3LHCYu22SKEYjj8"></span></p><span class="logistics-source-anchor" id="缺点" aria-hidden="true"></span><h3 id="disadvantages" tabindex="-1">Disadvantages <a class="header-anchor" href="#disadvantages" aria-label="Permalink to &quot;Disadvantages&quot;">​</a></h3><p>1. Full-storage overflow requires one Forge, one crucible and one transmuting unit per module, because we assume uneven depositing into storage—one disadvantage arising from this project&#39;s advantages. The footprint is enormous: Jingyu Valley + Marker Stone fit only dual SC Wuling Battery production + 12 Xiranite units + single-core Cuprium Canister + 4 Thermal Banks, with no possibility of all-item compatibility.</p><p>2. The many facilities consume substantial power: 5 pumps in Jingyu Valley and 10 in Marker Stone.</p><p>3. Heavy Xiranite rates are hard to measure: fluctuations are so large that even a 2h report barely becomes a straight line.</p><p>4. (I have not thought of another?)</p><p><span id="source-block-XqdOgNCClJgFZ0LdJZ4s0s"></span></p><span class="logistics-source-anchor" id="优点" aria-hidden="true"></span><h3 id="advantages" tabindex="-1">Advantages <a class="header-anchor" href="#advantages" aria-label="Permalink to &quot;Advantages&quot;">​</a></h3><p>1. The Xiranite module has a broad 0–360 oscillation range and an 8+4 modular structure. Players with incomplete technology and 4 or 8 Forges are supported, provided Xiranite output covers Xircon/Separator Core consumption.</p><p>2. It ignores all depositing round-robin/priority phenomena. Every Forge has its own overflow component; no loader misbehavior affects the structure.</p><p>3. Additional modules can be added freely provided total Xiranite draw does not exceed 360 and Cuprium draw does not exceed 240. (The 240 ceiling could be raised, but I am lazy.) For Chubby Lung, choose any available module you like and rate-limit it if it draws too much. No specially designed oversupply line is needed. The supplied Xircon/Separator Core lines can likewise be replaced with whichever you prefer.</p><p>4. After Cuprium-series and battery storage fill, Heavy Xiranite runs at full rate. All three outposts can then sell only Heavy Xiranite and still meet voucher requirements.</p><p>5. No cross-region conduits are mandatory except those for gas deposits in the North Wuling Exclusion Zone.</p><p><span id="source-block-AkQqjf8DvpLOSWMmq8YKa7"></span></p><span class="logistics-source-anchor" id="安装参考蓝图" aria-hidden="true"></span><h2 id="installation-reference-blueprints" tabindex="-1">Installation Reference Blueprints <a class="header-anchor" href="#installation-reference-blueprints" aria-label="Permalink to &quot;Installation Reference Blueprints&quot;">​</a></h2><p>1. Yinglung Pass: unchanged from 1.5 automatic gross production.</p><p>2. Jingyu Valley:</p><p>Upper half: dual-core SC Wuling Battery line. Arknights: Endfield blueprint [5022 Batteries], sharing code EF0170i9147e65eIO0Ai. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4edbb777a3cd639a.q90-12870dda85e2a908.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Lower half: four-core adaptive Xiranite full-storage overflow, connected to 5 pumps. Arknights: Endfield blueprint [Sub-Base 4 Xiranite], sharing code EF018OIEEe562159UI73. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-311d4cd47d814b9b.q90-954cdcc125a71ed7.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>If you want conduits throughout, space for them remains at the lower left. Connect 1 pump to each water control port and preferably 2 gas deposits to the Inergen outlet to avoid warm-up problems.</p><p>3. Marker Stone: eight-core adaptive Xiranite full-storage overflow.</p><p>Arknights: Endfield blueprint [8 Xiranite Main Structure], sharing code EF01ao6u52io8AaAoe5e. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Xiranite Fluid-Gas], sharing code EF01i1U9I341a28u72U4. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Heavy Xiranite Solidification], sharing code EF01eaA00o12940EoAi8. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1c83441a19437f05.q90-2c7838c137e88c42.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-61694a6bccb6c926.q90-a44791dfa74e8241.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Connect 10 pumps; the central Inergen conduit needs three gas deposits. Configure PAC unloaders according to the control ports. Plants start automatically, requiring no manual filling.</p><p>4. Main base:</p><p>Arknights: Endfield blueprint [Xircon with Yazhen Syringe [C]], sharing code EF012UOAA97oi845eIOo. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4e49f56beb017460.q90-4575beee9c73e449.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Cuprium Pretreatment: Refining], sharing code EF01A6711u9OaE4e9ieO. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Cuprium Pretreatment: Shredding], sharing code EF0170i998a4653uO0Ai. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a19c4d9f18eb5db1.q90-a6ac0df754927436.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Sewage with Yazhen Syringe [C]], sharing code EF011I934EAIoU8834O7. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Separator Core], sharing code EF016u082OUuI730O83e. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Batteries (Small)], sharing code EF015i2U19IieuoAeIoe. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-51c9afe8c13c7f16.q90-b6209d7ac1ae5bea.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Optional Heavy Xiranite], sharing code EF01081IO4e83iO8E179. Copy and use in the game.</p><p>This Heavy Xiranite blueprint is only for players who have brought Xiragen to the main base. Otherwise do not place it.</p><p>Pyrrolite Part production is also an optional add-on; its blueprint code is not supplied here.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-152e938a0e895fc2.q90-1424ac4b4b8dc296.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>That is all for now?</p><p><span id="source-block-4Rgtkmau5rMjRlvjCEWZdC"></span></p><span class="logistics-source-anchor" id="借物表" aria-hidden="true"></span><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Dual-core SC Wuling Battery: Xersyo</p><p>Eight-core Xiranite main structure: Xersyo, BEAR</p><p>Four-core Xiranite Fluid-Gas Transmuting Units: 断懒</p><p>Three-core Heavy Xiranite: 言</p><p>Xircon &amp; Yazhen Syringe [C]: 赫塔</p><p><span id="source-block-3tlSsgGr1OVgMgyYCLES9N"></span></p><span class="logistics-source-anchor" id="第二版主基地" aria-hidden="true"></span><h2 id="second-version-main-base" tabindex="-1">Second-Version Main Base <a class="header-anchor" href="#second-version-main-base" aria-label="Permalink to &quot;Second-Version Main Base&quot;">​</a></h2><p>Updated 2026.10.7.</p><p>Removed Protocol Stashes and redundant logistics structures. Open spaces, unused Depot Bus Sections and Bus Ports remain available for DIY.</p><p><span id="source-block-0NfqOk7rc2oMUoX03XG2mv"></span></p><span class="logistics-source-anchor" id="其余三个分基地与第一版无改动" aria-hidden="true"></span><h3 id="the-other-three-sub-bases-are-unchanged-from-version-one" tabindex="-1"><span class="mark-rose_red">The Other Three Sub-Bases Are Unchanged from Version One</span> <a class="header-anchor" href="#the-other-three-sub-bases-are-unchanged-from-version-one" aria-label="Permalink to &quot;&lt;span class=&quot;mark-rose_red&quot;&gt;The Other Three Sub-Bases Are Unchanged from Version One&lt;/span&gt;&quot;">​</a></h3><p>Blueprint codes no longer include bus sections; place them yourself. I moved the Bus Port several times during installation, making it awkward to include in the codes.</p><p>Arknights: Endfield blueprint [Yazhen Syringe [C] + Xircon], sharing code EF01eaA6ou5a0443oAi8. Copy and use in the game.</p><p>The manifold beside the Seed-Picking Unit connects two pumps; the other manifold one pump. The single-port conduit is for Purification Node Xircon Effluent.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-34889ae02c0e5e23.q90-36110d90fcdb799c.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Yazhen Syringe [C]], sharing code EF01081IO4e83iu1E179. Copy and use in the game.</p><p>The medicine-solution conduit is included in the previous blueprint.</p><p>Arknights: Endfield blueprint [Equipment Components], sharing code EF011I934EAIoUOo34O7. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Hetonite Part], sharing code EF012UOe9a3UA8iaeIOo. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Pyrrolite Part], sharing code EF01Oe4Aa6oe7I5A9oe4. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-565de5bf2a4ec99d.q90-8fa5f4f8bc6066dd.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a2058ac5d8b5feef.q90-983bb6319f0b1689.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Xircon Line: Overflow-Safe Sewage], sharing code EF0193aoE573ue7U5uI2. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b19fd0eeb4cf33bd.q90-51642d08a496e0ce.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Cuprium Pretreatment: Large], sharing code EF01ao6u52io8Aiuoe5e. Copy and use in the game.</p><p>Dual-port conduit, 4 pumps.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14609ab4c4788ed7.q90-062f038688336d60.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Cuprium Pretreatment: Small], sharing code EF01081IO4e83iuiE179. Copy and use in the game.</p><p>Single-port conduit, two pumps.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5e508c9c8d3f88d9.q90-148df49061a66e38.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Separator Core], sharing code EF011I934EAIoUOO34O7. Copy and use in the game.</p><p>Arknights: Endfield blueprint [Batteries + Cuprium], sharing code EF015i2U19IieuAEeIoe. Copy and use in the game.</p><p>Single-port conduit, one pump.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c15c93c864afd4d5.q90-62128d63da4db08b.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Separator Core], sharing code EF01U9ea3oE96O6I7Oa8. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c21f6f7ce4083120.q90-0a22bbbb116c2e7a.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p>Arknights: Endfield blueprint [Optional Heavy Xiranite], sharing code EF01081IO4e83iuOE179. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f3adb6237981476e.q90-ee940c4449dcb999.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fe67ea544bff2484.q90-3ae09df3b14d8919.webp" alt="Full-Storage Overflow Compatible with 15 Automatic Gross Production"></p><p><a href="/endfield-skydoc/frequently-asked-questions-about-full-storage-overflow">Frequently Asked Questions about Full-Storage Overflow</a></p></div>',1)])])}const h=a(r,[["render",s]]);export{g as __pageData,h as default};
